    alphabet = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"
    # Karakterlerin sırasını bir sözlükte tutalım (hızlı erişim için)
    char_order = {char: i for i, char in enumerate(alphabet)}

    def get_sort_key(word: str):
        # Kelimeyi Türkçe kurallarına göre küçültüyoruz
        lower_word = tr_lower(word)
        key = []
        for char in lower_word:
            if char in char_order:
                # Harf ise alfabetik sırasını ekle
                key.append((0, char_order[char]))
            else:
                # Diğer karakterler (boşluk, noktalama vb.) en başta gelir.
                # Kendi aralarında Unicode kod noktasına göre sıralanır.
                key.append((-1, ord(char)))
        return key

    # Python'un sorted() metodu 'stable'dır (eşit olanların sırasını korur).
    # Bu yüzden sadece get_sort_key kullanmamız yeterli.
    return sorted(words, key=get_sort_key)

